window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bc75ec3153f2fd1d"]={"versions": [{"id": "FIG-bc75ec3153f2fd1d", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellenspezifikation im Kontext des AUTOSAR Diagnostic Communication Manager (DCM, BSW). Das Diagramm modelliert die statische Abhängigkeit des DCM-Moduls von applikations- bzw. fahrzeugspezifischen Steuerungsfunktionen zur Bedienung des standardisierten On-Board-Diagnosedienstes OBD Service $08 („Request Control of On-Board System, Test or Component“) gemäß ISO 15031-5 / SAE J1979.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«module» Dcm</code>: BSW-Komponente des Diagnostic Communication Manager, welche eingehende Diagnoseanfragen verarbeitet und an die zuständigen Funktionen weiterleitet.\n</li><li><code>«interface» RequestControlServices_&lt;TID&gt;</code>: Parametrische Schnittstelle, die spezifisch pro unterstützter Test Identifier (<code>&lt;TID&gt;</code>) konfiguriert wird. Definiert die synchrone Operation:\n<ul class=\"fig-list\"><li><code>RequestControl(return :Std_ReturnType, OutBuffer :uint8*, InBuffer :uint8*)</code>: Funktionsaufruf zur Ausführung der Steuerungsroutine.\n<ul class=\"fig-list\"><li><code>return :Std_ReturnType</code>: Rückgabewert des Serviceaufrufs (<code>E_OK</code>, <code>E_NOT_OK</code>).\n</li><li><code>InBuffer :uint8*</code>: Zeiger auf Eingabedaten aus der Tester-Anforderung.\n</li><li><code>OutBuffer :uint8*</code>: Zeiger auf den Antwortpuffer für vom System zurückzugebende Daten.\n</li></ul>\n</li></ul>\n</li><li><code>«configurable»</code>: Gerichtete Abhängigkeitsbeziehung (Dependency) vom <code>Dcm</code> zur Schnittstelle <code>RequestControlServices_&lt;TID&gt;</code>, die anzeigt, dass die Bindung und Port-Realisierung zur Entwurfs-/Konfigurationszeit je TID projektiert wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellen- und Strukturdiagramm ohne explizite Zeitachse. Der implizite Steuerungs- und Datenfluss bei Diagnoseanfragen gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li>Der DCM empfängt einen OBD Service $08 Request mit Angabe einer konkreten Test-ID (<code>TID</code>).\n</li><li>Über die statische Konfiguration adressiert der DCM die der <code>TID</code> zugeordnete Schnittstelleninstanz <code>RequestControlServices_&lt;TID&gt;</code>.\n</li><li>Der DCM ruft synchron die Operation <code>RequestControl</code> auf und übergibt die Anforderungs-Nutzlast (<code>InBuffer</code>) sowie die Referenz auf den Antwortpuffer (<code>OutBuffer</code>).\n</li><li>Die implementierende Funktionsinstanz führt die Steuerungsaktion aus, beschreibt <code>OutBuffer</code> und meldet den Ausführungsstatus via <code>Std_ReturnType</code> zurück.\n</li><li>Der DCM bewertet das Ergebnis und generiert die positive bzw. negative OBD-Antwortnachricht an das Diagnose-Tool.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Schnittstellenbindung</strong>: Die Signatur von <code>RequestControl</code> ist bindend für alle durch den DCM per Service $08 angebundenen externen Funktionen.\n</li><li><strong>Konfigurationsaspekt</strong>: Die Namenskonvention mit dem Platzhalter <code>&lt;TID&gt;</code> verlangt eineindeutige Zuordnungen im AUTOSAR-DCM-Konfigurationsmodell für jede vom Steuergerät unterstützte TID.\n</li><li><strong>Speichermanagement</strong>: Die Übergabe von Raw-Pointern (<code>uint8*</code>) erfordert strikte Einhaltung der in ISO 15031-5 / SAE J1979 definierten Längen für Eingangs- und Ausgangsdaten, um Pufferüberläufe im DCM bzw. der implementierenden SW-C zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-43bb678af5688196", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellenspezifikation im Kontext des AUTOSAR Diagnostic Communication Manager (DCM, BSW). Das Diagramm modelliert die statische Abhängigkeit des DCM-Moduls von applikations- bzw. fahrzeugspezifischen Steuerungsfunktionen zur Bedienung des standardisierten On-Board-Diagnosedienstes OBD Service $08 („Request Control of On-Board System, Test or Component“) gemäß ISO 15031-5 / SAE J1979.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«module» Dcm</code>: BSW-Komponente des Diagnostic Communication Manager, welche eingehende Diagnoseanfragen verarbeitet und an die zuständigen Funktionen weiterleitet.\n</li><li><code>«interface» RequestControlServices_&lt;TID&gt;</code>: Parametrische Schnittstelle, die spezifisch pro unterstützter Test Identifier (<code>&lt;TID&gt;</code>) konfiguriert wird. Definiert die synchrone Operation:\n<ul class=\"fig-list\"><li><code>RequestControl(return :Std_ReturnType, OutBuffer :uint8*, InBuffer :uint8*)</code>: Funktionsaufruf zur Ausführung der Steuerungsroutine.\n<ul class=\"fig-list\"><li><code>return :Std_ReturnType</code>: Rückgabewert des Serviceaufrufs (<code>E_OK</code>, <code>E_NOT_OK</code>).\n</li><li><code>InBuffer :uint8*</code>: Zeiger auf Eingabedaten aus der Tester-Anforderung.\n</li><li><code>OutBuffer :uint8*</code>: Zeiger auf den Antwortpuffer für vom System zurückzugebende Daten.\n</li></ul>\n</li></ul>\n</li><li><code>«configurable»</code>: Gerichtete Abhängigkeitsbeziehung (Dependency) vom <code>Dcm</code> zur Schnittstelle <code>RequestControlServices_&lt;TID&gt;</code>, die anzeigt, dass die Bindung und Port-Realisierung zur Entwurfs-/Konfigurationszeit je TID projektiert wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellen- und Strukturdiagramm ohne explizite Zeitachse. Der implizite Steuerungs- und Datenfluss bei Diagnoseanfragen gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li>Der DCM empfängt einen OBD Service $08 Request mit Angabe einer konkreten Test-ID (<code>TID</code>).\n</li><li>Über die statische Konfiguration adressiert der DCM die der <code>TID</code> zugeordnete Schnittstelleninstanz <code>RequestControlServices_&lt;TID&gt;</code>.\n</li><li>Der DCM ruft synchron die Operation <code>RequestControl</code> auf und übergibt die Anforderungs-Nutzlast (<code>InBuffer</code>) sowie die Referenz auf den Antwortpuffer (<code>OutBuffer</code>).\n</li><li>Die implementierende Funktionsinstanz führt die Steuerungsaktion aus, beschreibt <code>OutBuffer</code> und meldet den Ausführungsstatus via <code>Std_ReturnType</code> zurück.\n</li><li>Der DCM bewertet das Ergebnis und generiert die positive bzw. negative OBD-Antwortnachricht an das Diagnose-Tool.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Schnittstellenbindung</strong>: Die Signatur von <code>RequestControl</code> ist bindend für alle durch den DCM per Service $08 angebundenen externen Funktionen.\n</li><li><strong>Konfigurationsaspekt</strong>: Die Namenskonvention mit dem Platzhalter <code>&lt;TID&gt;</code> verlangt eineindeutige Zuordnungen im AUTOSAR-DCM-Konfigurationsmodell für jede vom Steuergerät unterstützte TID.\n</li><li><strong>Speichermanagement</strong>: Die Übergabe von Raw-Pointern (<code>uint8*</code>) erfordert strikte Einhaltung der in ISO 15031-5 / SAE J1979 definierten Längen für Eingangs- und Ausgangsdaten, um Pufferüberläufe im DCM bzw. der implementierenden SW-C zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-bc75ec3153f2fd1d", "to": "FIG-43bb678af5688196", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Diagrammrahmen</strong>: Der äußere UML-Rahmen mit der Kopfzeile <code>class OBD Service $08</code> wurde entfernt.\n</li><li><strong>Modulsymbolik (<code>Dcm</code>)</strong>: Das interne Konnektorsymbol (<code>o-o</code>) in der rechten unteren Ecke des Komponentenblocks <code>«module» Dcm</code> wurde entfernt.\n</li><li><strong>Typografie (<code>RequestControlServices_&lt;TID&gt;</code>)</strong>: Die Formatierung des Schnittstellennamens wurde von fett/kursiv auf Standard-Schriftschnitt vereinheitlicht.\n</li><li><strong>Grafische Gestaltung</strong>: Schlagschatten an den UML-Elementen (<code>«interface»</code> und <code>«module»</code>) wurden entfernt (flache Darstellung).\n</li></ul>"}]};
